"""Safe, read-only query execution. The ONLY SQL that reaches DuckDB is generated by services.formula.Compiler."""
from __future__ import annotations

import datetime as dt
import math
import re
import threading
import time
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path

import duckdb
from sqlalchemy import select
from sqlalchemy.orm import Session

from ..config import settings
from .calendar_in import fy_bounds, fy_start_year, today_ist
from ..models import Dataset, Execution, Metric, MetricVersion
from .formula import (
    GRAINS,
    Compiler,
    FormulaError,
    Parsed,
    categorize,
    parse_condition,
    parse_formula,
    qident,
)


class QueryTimeout(Exception):
    pass


class QueryError(Exception):
    pass


def dataset_schema(ds: Dataset) -> dict[str, str]:
    return {c["name"]: c["category"] for c in (ds.schema_json or [])}


def to_jsonable(v):
    if v is None:
        return None
    if isinstance(v, Decimal):
        v = float(v)
    if isinstance(v, float):
        return None if (math.isnan(v) or math.isinf(v)) else v
    if isinstance(v, (dt.datetime,)):
        return v.isoformat(sep=" ")
    if isinstance(v, (dt.date, dt.time)):
        return v.isoformat()
    if isinstance(v, (bytes, bytearray)):
        return v.hex()
    if isinstance(v, (int, str, bool)):
        return v
    return str(v)


def connect_parquet(path: str) -> duckdb.DuckDBPyConnection:
    p = Path(path).resolve()
    if not p.exists():
        raise QueryError("Dataset file is missing on disk")
    con = duckdb.connect(":memory:")
    con.execute("SET threads TO 4")
    escaped = str(p).replace("'", "''")
    con.execute(f"CREATE VIEW data AS SELECT * FROM read_parquet('{escaped}')")
    return con


def window_range(window: str | None, today: dt.date | None = None) -> tuple[str, str] | None:
    """Metric time windows. 'ytd' means FINANCIAL-year-to-date (1 April), per the Indian fiscal calendar."""
    today = today or today_ist()
    if not window or window == "all_time":
        return None
    if window in ("ytd", "this_fy"):
        return fy_bounds(fy_start_year(today))[0].isoformat(), today.isoformat()
    if window == "mtd":
        return today.replace(day=1).isoformat(), today.isoformat()
    if window == "last_12_months":
        return (today - dt.timedelta(days=365)).isoformat(), today.isoformat()
    if window == "last_30_days":
        return (today - dt.timedelta(days=30)).isoformat(), today.isoformat()
    if window == "last_90_days":
        return (today - dt.timedelta(days=90)).isoformat(), today.isoformat()
    return None


TIME_WINDOWS = ["all_time", "ytd", "mtd", "last_12_months", "last_90_days", "last_30_days"]


@dataclass
class QuerySpec:
    formula: str
    filters: str | None = None  # metric-level condition
    dimensions: list[dict] = field(default_factory=list)  # [{column, grain?}]
    time_range: dict | None = None  # {column?, start, end}
    where: list[dict] = field(default_factory=list)  # [{column, op, value}]
    order: str = "dim"  # dim | value_desc | value_asc
    limit: int = 1000


@dataclass
class QueryResult:
    columns: list[str]
    rows: list[list]
    sql: str
    params: list
    duration_ms: float
    scanned_rows: int
    truncated: bool = False
    metrics_used: list[str] = field(default_factory=list)
    columns_used: list[str] = field(default_factory=list)


def _coerce_value(cat: str, v):
    if cat == "numeric":
        try:
            return float(v) if not isinstance(v, (int, float)) else v
        except (TypeError, ValueError):
            raise FormulaError(f"Value {v!r} is not numeric")
    if cat == "bool":
        return bool(v)
    return str(v)


ALLOWED_OPS = {"=": "=", "!=": "<>", ">": ">", ">=": ">=", "<": "<", "<=": "<=", "in": "IN"}


def build_sql(ds: Dataset, spec: QuerySpec, resolver=None) -> tuple[str, list, dict]:
    schema = dataset_schema(ds)
    lower = {k.lower(): k for k in schema}
    comp = Compiler(schema, resolver)
    parsed = parse_formula(spec.formula)
    extra = [parse_condition(spec.filters)] if spec.filters and spec.filters.strip() else []
    res = comp.compile_formula(parsed, extra)

    select_parts: list[str] = []
    group_parts: list[str] = []
    for d in spec.dimensions:
        real = lower.get(str(d.get("column", "")).lower())
        if not real:
            raise FormulaError(f"Unknown dimension column '{d.get('column')}'")
        grain = d.get("grain")
        if grain:
            if grain not in GRAINS:
                raise FormulaError(f"Invalid time grain '{grain}'")
            if schema[real] != "date":
                raise FormulaError(f"Time grain requires a date column; '{real}' is {schema[real]}")
            expr = f"CAST(date_trunc('{grain}', {qident(real)}) AS DATE)"
        else:
            expr = qident(real)
        select_parts.append(f"{expr} AS {qident(real)}")
        group_parts.append(expr)

    where_sql: list[str] = []
    where_params: list = []
    for w in res.where:
        where_sql.append(w.sql)
        where_params += w.params
    tr = spec.time_range
    if tr and (tr.get("start") or tr.get("end")):
        col = tr.get("column") or ds.date_column
        real = lower.get((col or "").lower())
        if not real or schema[real] != "date":
            raise FormulaError("Time range requires a date column on the dataset")
        if tr.get("start"):
            where_sql.append(f"CAST({qident(real)} AS DATE) >= CAST(? AS DATE)")
            where_params.append(_check_date(tr["start"]))
        if tr.get("end"):
            where_sql.append(f"CAST({qident(real)} AS DATE) <= CAST(? AS DATE)")
            where_params.append(_check_date(tr["end"]))
    for f in spec.where:
        real = lower.get(str(f.get("column", "")).lower())
        if not real:
            raise FormulaError(f"Unknown filter column '{f.get('column')}'")
        op = f.get("op", "=")
        if op not in ALLOWED_OPS:
            raise FormulaError(f"Unsupported filter operator '{op}'")
        cat = schema[real]
        if op == "in":
            vals = f.get("value") or []
            if not isinstance(vals, list) or not vals or len(vals) > 200:
                raise FormulaError("IN filter needs a non-empty list (max 200)")
            ph = ", ".join(["?"] * len(vals))
            where_sql.append(f"{qident(real)} IN ({ph})")
            where_params += [_cast_param(cat, v) for v in vals]
        else:
            sqlv = "CAST(? AS DATE)" if cat == "date" else "?"
            where_sql.append(f"{qident(real)} {ALLOWED_OPS[op]} {sqlv}")
            where_params.append(_cast_param(cat, f.get("value")))

    value_alias = '"value"'
    sel = ", ".join(select_parts + [f"{res.sql} AS {value_alias}"])
    sql = f"SELECT {sel} FROM data"
    if where_sql:
        sql += " WHERE " + " AND ".join(where_sql)
    if group_parts:
        sql += " GROUP BY " + ", ".join(group_parts)
    if spec.order == "value_desc":
        sql += f" ORDER BY {value_alias} DESC NULLS LAST"
    elif spec.order == "value_asc":
        sql += f" ORDER BY {value_alias} ASC NULLS LAST"
    elif group_parts:
        sql += " ORDER BY " + ", ".join(str(i + 1) for i in range(len(group_parts)))
    limit = max(1, min(int(spec.limit or 1000), settings.QUERY_ROW_LIMIT))
    sql += f" LIMIT {limit + 1}"  # +1 detects truncation
    params = list(res.params) + where_params
    meta = {
        "limit": limit,
        "dims": [d["column"] for d in spec.dimensions],
        "metrics": res.metrics,
        "columns": sorted(res.columns),
        "aggregations": sorted(res.aggregations),
    }
    return sql, params, meta


def _check_date(v) -> str:
    s = str(v)[:10]
    try:
        dt.date.fromisoformat(s)
    except ValueError:
        raise FormulaError(f"Invalid date '{v}'")
    return s


def _cast_param(cat: str, v):
    if cat == "date":
        return _check_date(v)
    return _coerce_value(cat, v)


def execute_sql(ds: Dataset, sql: str, params: list, limit: int) -> QueryResult:
    timeout = settings.QUERY_TIMEOUT_SECONDS
    con = connect_parquet(ds.parquet_path or "")
    timer = threading.Timer(timeout, con.interrupt)
    start = time.perf_counter()
    try:
        timer.start()
        cur = con.execute(sql, params)
        cols = [d[0] for d in cur.description]
        raw = cur.fetchall()
    except duckdb.InterruptException:
        raise QueryTimeout(f"Query exceeded the {timeout}s time limit")
    except duckdb.Error as e:
        raise QueryError(f"Query failed: {str(e).splitlines()[0]}")
    finally:
        timer.cancel()
        con.close()
    ms = (time.perf_counter() - start) * 1000
    truncated = len(raw) > limit
    rows = [[to_jsonable(v) for v in r] for r in raw[:limit]]
    return QueryResult(cols, rows, sql, params, round(ms, 2), ds.row_count or 0, truncated)


def run_query(
    db: Session,
    ds: Dataset,
    spec: QuerySpec,
    user_id: str | None,
    kind: str = "execute",
    resolver=None,
    record: bool = True,
) -> QueryResult:
    """Compile + execute + log. Raises FormulaError / QueryError / QueryTimeout (all logged)."""
    started = time.perf_counter()
    sql_text = None
    try:
        if ds.status != "ready" or not ds.parquet_path:
            raise QueryError("Dataset is not ready (still processing or failed)")
        sql, params, meta = build_sql(ds, spec, resolver)
        sql_text = sql
        res = execute_sql(ds, sql, params, meta["limit"])
        res.metrics_used = meta["metrics"]
        res.columns_used = meta["columns"]
        if record:
            db.add(
                Execution(
                    workspace_id=ds.workspace_id, user_id=user_id, dataset_id=ds.id, kind=kind,
                    expression=spec.formula, ok=True, duration_ms=res.duration_ms,
                    scanned_rows=res.scanned_rows, row_count=len(res.rows), sql_text=sql,
                )
            )
        return res
    except (FormulaError, QueryError, QueryTimeout) as e:
        if record:
            db.add(
                Execution(
                    workspace_id=ds.workspace_id, user_id=user_id, dataset_id=ds.id, kind=kind,
                    expression=spec.formula, ok=False,
                    duration_ms=round((time.perf_counter() - started) * 1000, 2),
                    scanned_rows=0, row_count=0, error=getattr(e, "message", str(e)), sql_text=sql_text,
                )
            )
        raise


# ----------------------------------------------------------------------------- metric resolution
def slugify(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", name.lower()).strip("_")[:100] or "metric"


def live_definition(db: Session, m: Metric, pinned_version: int | None = None) -> dict | None:
    """Definition used by dashboards/chat: pinned version snapshot, else latest published snapshot,
    else (approved, never published) the working copy. None if not usable."""
    num = pinned_version or m.published_version
    if num:
        v = db.scalar(select(MetricVersion).where(MetricVersion.metric_id == m.id, MetricVersion.number == num))
        if v:
            snap = dict(v.snapshot)
            snap["_version"] = v.number
            return snap
    if m.status in ("approved", "published"):
        return {**metric_snapshot(m), "_version": m.version}
    return None


def metric_snapshot(m: Metric) -> dict:
    return {
        "key": m.key, "name": m.name, "description": m.description, "business_definition": m.business_definition,
        "formula": m.formula, "filters": m.filters, "aggregation": m.aggregation, "unit": m.unit,
        "time_window": m.time_window, "date_column": m.date_column, "dataset_id": m.dataset_id,
        "department": m.department, "category": m.category,
    }


def make_resolver(db: Session, workspace_id: str, dataset_id: str, mode: str = "live", pins: dict | None = None):
    """Resolves [Metric Name] references. mode='live' uses published snapshots; 'working' uses working copies
    (Formula Lab / validation) but still requires a live or approved metric of that name."""
    pins = pins or {}

    def resolve(name: str):
        low = name.lower()
        rows = db.scalars(select(Metric).where(Metric.workspace_id == workspace_id)).all()
        cand = [m for m in rows if (m.name.lower() == low or m.key == slugify(name)) and m.status != "deprecated"]
        live = [m for m in cand if m.is_live]
        m = live[0] if live else None
        if m is None:
            return None
        snap = live_definition(db, m, pins.get(m.key)) if mode == "live" else metric_snapshot(m)
        if snap is None:
            return None
        if snap.get("dataset_id") != dataset_id:
            raise FormulaError(f"Metric [{name}] is defined on a different dataset; cross-dataset references are not supported")
        return parse_formula(snap["formula"]), (parse_condition(snap["filters"]) if snap.get("filters") else None)

    return resolve
